    public NoiseModeIcon()
    {
        InitializeComponent();
        Update();
    }

    public NoiseMode Mode
    {
        get => (NoiseMode)GetValue(ModeProperty);
        set => SetValue(ModeProperty, value);
    }

    private void Update()
    {
        // Material grid: 960 units, top at y = -960. The web app's icon: 25 units wide.
        var (data, scale, offsetY) = Mode switch
        {
            NoiseMode.Off          => (NoiseControlOff, 24.0 / 960, 24.0),
            NoiseMode.Transparency => (NoiseAware, 24.0 / 960, 24.0),
            NoiseMode.Adaptive     => (AdaptiveAnc, 24.0 / 25, 0.0),
            _                      => (NoiseControlOn, 24.0 / 960, 24.0),
        };

        // F1 = nonzero fill, which SVG uses by default
        var geometry = (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), "F1 " + data);
        geometry.Transform = new MatrixTransform { Matrix = new Matrix(scale, 0, 0, scale, 0, offsetY) };
        Icon.Data = geometry;
    }
